package br.com.rodrigosantana.maqflow.service;
import br.com.rodrigosantana.maqflow.dto.user.UserRequestDTO;import br.com.rodrigosantana.maqflow.entity.User;import br.com.rodrigosantana.maqflow.enums.Role;import br.com.rodrigosantana.maqflow.exception.DuplicateEmailException;import br.com.rodrigosantana.maqflow.repository.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class UserServiceTest {@Test void rejectsDuplicateEmail(){UserRepository users=mock(UserRepository.class);EquipmentRepository eq=mock(EquipmentRepository.class);MaintenanceRepository mt=mock(MaintenanceRepository.class);when(users.existsByEmail("a@b.com")).thenReturn(true);UserService service=new UserService(users,eq,mt);assertThrows(DuplicateEmailException.class,()->service.create(new UserRequestDTO("A","a@b.com","secret",Role.USER)));verify(users,never()).save(any(User.class));}}
